package provider

import (
	"archive/zip"
	"bytes"
	"os"
	"strings"
	"testing"
)

const validProfile = `client
proto udp
remote vpn.example.test 1194
dev tun
auth-user-pass
compress
<ca>
-----BEGIN CERTIFICATE-----
test-certificate
-----END CERTIFICATE-----
</ca>
`

// TestNormalizeOpenVPNProfileForcesSafetyOptions verifies the safe profile rewrite.
//
// Provider compression and credential-path directives are removed while the required
// tunnel and authentication controls are generated by the appliance.
func TestNormalizeOpenVPNProfileForcesSafetyOptions(testingObject *testing.T) {
	profile, err := NormalizeOpenVPNProfile(
		"custom",
		"example-udp.ovpn",
		[]byte(validProfile),
	)
	if err != nil {
		testingObject.Fatalf("normalize profile: %v", err)
	}

	configuration := string(profile.Configuration)
	requiredText := []string{
		"dev tun0",
		"auth-user-pass /run/transmission-vpn/openvpn/auth",
		"allow-compression no",
		"remote vpn.example.test 1194",
	}
	for _, expectedText := range requiredText {
		if !strings.Contains(configuration, expectedText) {
			testingObject.Errorf("normalized profile does not contain %q", expectedText)
		}
	}

	if strings.Contains(configuration, "\ncompress\n") {
		testingObject.Fatal("provider compression directive was retained")
	}
	if strings.Contains(configuration, "redirect-gateway") {
		testingObject.Fatal("normalizer forced a main-table default route")
	}
	if _, err := ValidateNormalizedOpenVPNProfile(profile.Configuration); err != nil {
		testingObject.Fatalf("validator required redirect-gateway: %v", err)
	}

	if profile.RemoteHost != "vpn.example.test" || profile.RemotePort != 1194 ||
		profile.Protocol != "udp" {
		testingObject.Fatalf("unexpected endpoint metadata: %+v", profile)
	}
}

// TestNormalizeOpenVPNProfilesSplitsRemoteFallbacks preserves file order.
func TestNormalizeOpenVPNProfilesSplitsRemoteFallbacks(testingObject *testing.T) {
	content := strings.Replace(
		validProfile,
		"remote vpn.example.test 1194",
		"remote vpn-toronto.example.test 1194\nremote vpn-montreal.example.test 443 tcp-client",
		1,
	)
	profiles, err := NormalizeOpenVPNProfiles("custom", "canada.ovpn", []byte(content))
	if err != nil {
		testingObject.Fatalf("normalize endpoint pool: %v", err)
	}
	if len(profiles) != 2 || profiles[0].RemoteHost != "vpn-toronto.example.test" ||
		profiles[1].RemoteHost != "vpn-montreal.example.test" || profiles[1].Protocol != "tcp" {
		testingObject.Fatalf("profiles = %+v", profiles)
	}
	for index, profile := range profiles {
		if strings.Count(string(profile.Configuration), "\nremote ") != 1 {
			testingObject.Fatalf("profile %d configuration contains more than one remote:\n%s", index, profile.Configuration)
		}
		if _, validationError := ValidateNormalizedOpenVPNProfile(profile.Configuration); validationError != nil {
			testingObject.Fatalf("profile %d fails controller validation: %v", index, validationError)
		}
	}
}

// TestOfficialPureVPNCatalog validates an explicitly supplied current provider bundle.
//
// Normal test runs skip this network-derived fixture; release verification supplies the
// downloaded official ZIP to detect upstream format or directive changes.
func TestOfficialPureVPNCatalog(testingObject *testing.T) {
	catalogPath := os.Getenv("PUREVPN_CATALOG_TEST_PATH")
	if catalogPath == "" {
		testingObject.Skip("PUREVPN_CATALOG_TEST_PATH is not set")
	}

	content, err := os.ReadFile(catalogPath)
	if err != nil {
		testingObject.Fatalf("read official PureVPN catalog: %v", err)
	}
	profiles, err := ParsePureVPNCatalog(content)
	if err != nil {
		testingObject.Fatalf("parse official PureVPN catalog: %v", err)
	}
	if len(profiles) < 50 {
		testingObject.Fatalf("official PureVPN catalog contains only %d profiles", len(profiles))
	}

	foundMigrationEndpoint := false
	for _, profile := range profiles {
		if profile.DisplayName == "de2-auto-udp-qr" {
			foundMigrationEndpoint = true
			break
		}
	}
	if !foundMigrationEndpoint {
		testingObject.Fatal("official PureVPN catalog lacks de2-auto-udp-qr")
	}
}

// TestOfficialPIACatalog validates explicitly supplied current UDP and TCP bundles.
func TestOfficialPIACatalog(testingObject *testing.T) {
	udpPath := os.Getenv("PIA_UDP_CATALOG_TEST_PATH")
	tcpPath := os.Getenv("PIA_TCP_CATALOG_TEST_PATH")
	if udpPath == "" || tcpPath == "" {
		testingObject.Skip("PIA catalog test paths are not set")
	}

	udpContent, err := os.ReadFile(udpPath)
	if err != nil {
		testingObject.Fatalf("read official PIA UDP catalog: %v", err)
	}
	tcpContent, err := os.ReadFile(tcpPath)
	if err != nil {
		testingObject.Fatalf("read official PIA TCP catalog: %v", err)
	}
	profiles, err := ParsePIACatalog([][]byte{udpContent, tcpContent})
	if err != nil {
		testingObject.Fatalf("parse official PIA catalog: %v", err)
	}
	if len(profiles) < 200 {
		testingObject.Fatalf("official PIA catalog contains only %d profiles", len(profiles))
	}
	for _, profile := range profiles {
		if profile.Country == "" || profile.Continent == "" {
			testingObject.Fatalf("PIA profile lacks location metadata: %+v", profile)
		}
	}
}

