// TestNormalizeOpenVPNProfileRejectsExecutableHooks protects the controller boundary.
//
// Profiles are configuration data and cannot raise script security or execute a hook
// even when the rest of the profile is valid.
func TestNormalizeOpenVPNProfileRejectsExecutableHooks(testingObject *testing.T) {
	unsafeProfile := strings.Replace(
		validProfile,
		"dev tun",
		"dev tun\nscript-security 2\nup /tmp/provider-hook",
		1,
	)

	if _, err := NormalizeOpenVPNProfile(
		"custom",
		"unsafe.ovpn",
		[]byte(unsafeProfile),
	); err == nil || !strings.Contains(err.Error(), "script-security") {
		testingObject.Fatalf("unsafe profile error = %v", err)
	}
}

// TestParsePureVPNCatalog validates ZIP traversal and profile normalization together.
//
// Catalog refreshes use this exact parser, so a valid bundle must produce stable
// PureVPN endpoints without trusting archive filenames as paths.
func TestParsePureVPNCatalog(testingObject *testing.T) {
	archive := catalogFixture(testingObject, "Recommended/OpenVPN/de2-auto-udp-qr.ovpn", validProfile)

	profiles, err := ParsePureVPNCatalog(archive)
	if err != nil {
		testingObject.Fatalf("parse catalog: %v", err)
	}
	if len(profiles) != 1 || profiles[0].ProviderID != "purevpn" {
		testingObject.Fatalf("unexpected catalog profiles: %+v", profiles)
	}
}

// TestParsePIACatalog derives searchable geography across both transport archives.
func TestParsePIACatalog(testingObject *testing.T) {
	udpProfile := strings.Replace(validProfile, "dev tun", "dev tun\ndisable-occ", 1)
	tcpProfile := strings.Replace(udpProfile, "proto udp", "proto tcp-client", 1)
	profiles, err := ParsePIACatalog([][]byte{
		catalogFixture(testingObject, "us_new_york.ovpn", udpProfile),
		catalogFixture(testingObject, "us_new_york.ovpn", tcpProfile),
	})
	if err != nil {
		testingObject.Fatalf("parse PIA catalog: %v", err)
	}
	if len(profiles) != 2 || profiles[0].Country != "United States" ||
		profiles[0].City != "New York" || profiles[0].Continent != "North America" {
		testingObject.Fatalf("unexpected PIA profiles: %+v", profiles)
	}
}

// TestParseIPVanishCatalog derives country, city, and server labels from filenames.
func TestParseIPVanishCatalog(testingObject *testing.T) {
	profileContent := strings.Replace(
		validProfile,
		"dev tun",
		"dev tun\npersist-remote-ip\nsetenv CLIENT_CERT 0",
		1,
	)
	profiles, err := ParseIPVanishCatalog(catalogFixture(
		testingObject,
		"configs/ipvanish-US-New-York-nyc-c28.ovpn",
		profileContent,
	))
	if err != nil {
		testingObject.Fatalf("parse IPVanish catalog: %v", err)
	}
	if len(profiles) != 1 || profiles[0].Country != "United States" ||
		profiles[0].City != "New York" || profiles[0].Continent != "North America" ||
		!strings.Contains(profiles[0].DisplayName, "NYC-C28") {
		testingObject.Fatalf("unexpected IPVanish profile: %+v", profiles)
	}
}

// catalogFixture creates one minimal ZIP catalog for adapter tests.
func catalogFixture(testingObject *testing.T, name string, content string) []byte {
	testingObject.Helper()

	var archive bytes.Buffer
	archiveWriter := zip.NewWriter(&archive)
	profileWriter, err := archiveWriter.Create(name)
	if err != nil {
		testingObject.Fatalf("create catalog entry: %v", err)
	}
	if _, err := profileWriter.Write([]byte(content)); err != nil {
		testingObject.Fatalf("write catalog entry: %v", err)
	}
	if err := archiveWriter.Close(); err != nil {
		testingObject.Fatalf("close catalog: %v", err)
	}

	return archive.Bytes()
}
